parameters.jsCode:
const item = $input.first();
const resp = item.json;
const pre = $('Extract Email & Resume Data').first().json;

let parsed = {};
try {
  const rawText = resp.candidates[0].content.parts[0].text;
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {
    candidateName: pre.candidateName || 'Candidate',
    candidateEmail: pre.senderEmail,
    appliedRole: pre.appliedRole,
    decision: 'REJECTED',
    matchScore: 50,
    evaluationSummary: 'Automated scan error. Fallback profile generated.',
    topSkills: ['General Skills'],
    strengths: ['Application Submitted'],
    areasForImprovement: ['Unformatted resume text'],
    interviewQuestions: [],
    emailSubject: `Update on your application for ${pre.appliedRole}`,
    emailBody: `Dear Candidate,\n\nThank you for your interest in the ${pre.appliedRole} position. At this time we are unable to advance your application.`
  };
}

// Ensure candidateEmail is valid
if (!parsed.candidateEmail || parsed.candidateEmail.includes('candidate@example.com')) {
  parsed.candidateEmail = pre.senderEmail;
}
if (!parsed.candidateName || parsed.candidateName === 'Full Name') {
  parsed.candidateName = pre.candidateName || parsed.candidateEmail.split('@')[0];
}

const now = new Date().toISOString();
const recordId = 'cand_' + Date.now().toString(36) + '_' + Math.random().toString(36).substring(2, 6);

const candidateRecord = {
  id: recordId,
  name: parsed.candidateName,
  email: parsed.candidateEmail,
  phone: parsed.candidatePhone || 'N/A',
  role: parsed.appliedRole || pre.appliedRole,
  decision: parsed.decision || (parsed.matchScore >= 70 ? 'SELECTED' : 'REJECTED'),
  matchScore: Number(parsed.matchScore) || 75,
  status: parsed.decision === 'SELECTED' ? 'INTERVIEW_SCHEDULED' : 'REJECTED',
  yearsOfExperience: parsed.yearsOfExperience || '3+',
  topSkills: Array.isArray(parsed.topSkills) ? parsed.topSkills : [],
  education: parsed.education || 'Graduate',
  strengths: Array.isArray(parsed.strengths) ? parsed.strengths : [],
  areasForImprovement: Array.isArray(parsed.areasForImprovement) ? parsed.areasForImprovement : [],
  evaluationSummary: parsed.evaluationSummary || '',
  rejectionReason: parsed.rejectionReason || null,
  interviewQuestions: Array.isArray(parsed.interviewQuestions) ? parsed.interviewQuestions : [],
  proposedInterviewDate: parsed.proposedInterviewDate || 'Upcoming Week',
  interviewStatus: parsed.decision === 'SELECTED' ? 'Invitation Sent - Awaiting Confirmation' : 'N/A',
  emailSubject: parsed.emailSubject,
  emailBody: parsed.emailBody,
  emailSentAt: now,
  createdAt: now,
  updatedAt: now,
  source: pre.hasAttachment ? 'Gmail Email Attachment' : 'Dashboard Direct Application'
};

return {
  json: candidateRecord
};

